mapper.select:
select
date_format(CDATE, '%Y-%m-%d') as HOLIDATE
from
VAL_VW_MST_HOLIDAY
where
IS_HOLIDAY > 0

    and CDATE >= #{startDate, jdbcType=DATE}


    and CDATE <= #{endDate, jdbcType=DATE}


    and TRADE_CALENDAR_ID = #{dealCalId}

SELECT T1.CASH_ID CASH_ID, T1.CASH_TYPE_1 CASH_TYPE_1, T1.CASH_TYPE_2 CASH_TYPE_2, T1.CCY CCY, T1.FINPROD_ID FINPROD_ID, T1.FINPROD_TYPE FINPROD_TYPE, T1.BRANCH BRANCH, T1.FEE_ID FEE_ID, T1.CHL_FINPROD_ID CHL_FINPROD_ID, T1.CHL_LEVEL CHL_LEVEL, T1.CREATE_USER CREATE_USER, T1.CREATE_DEPT CREATE_DEPT, T1.CREATE_TIME CREATE_TIME, T1.UPDATE_USER UPDATE_USER, T1.UPDATE_TIME UPDATE_TIME ,T2.FINPROD_ID FINPROD_ID , T2.FINPROD_TYPE FINPROD_TYPE , T2.FINPROD_TYPE2 FINPROD_TYPE2 , T2.FINPROD_ABBR FINPROD_ABBR , T2.FINPROD_NAME FINPROD_NAME , T2.COUPON_SPECIES , T3.EFF_DATE EFF_DATE , T3.PAY_CYCLE_VAL PAY_CYCLE_VAL , T3.PAY_CYCLE PAY_CYCLE , T3.DAY_TYPE DAY_TYPE , T3.DAY_VALUE DAY_VALUE , T3.END_TDAY_RULE END_TDAY_RULE , T3.PAY_TDAY_RULE PAY_TDAY_RULE , T3.CALC_RULE CALC_RULE , T3.FIRST_PAY_DATE FIRST_PAY_DATE , T3.CASH_UNIT_TYPE CASH_UNIT_TYPE ,T3.REMARK REMARK FROM FIN_CASH_INFO T1 LEFT JOIN FIN_PRODUCT T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_PAY_RULE T3 ON T3.CASH_ID = T1.CASH_ID
AND T3.EFF_DATE = str_to_date ( #{vdate}, '%Y-%m-%d' )
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T1.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T1.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
